<script setup lang="ts">
import ForegroundStatus from '../components/ForegroundStatus.vue';
import { computed, watch, onMounted, onUnmounted } from 'vue';
import { useRoute } from 'vue-router';
import * as setup from '../stores/setup.js';
import { manual } from '../stores/manual.js';
import { missingFact, setupChanges } from '../adapters/setup.js';
import AdminVoice from '../components/AdminVoice.vue';
import TaskErrors from '../components/forms/TaskErrors.vue';
const route = useRoute();
const { session, owned, entering, transitioning, setupBusy, setupNotice, setupIssues, composer, proposal, conversation, lane, zoneContext, deviceContext, facts, sharedChoice, selectedConsumers, proposalChanges, probeResult, canCancel, limits, promptSize, progressLabel, messagePending, cancelRequested, sendFeedback, sendFailed } = setup;
let progressTimer: ReturnType<typeof setInterval> | undefined;
onMounted(() => { progressTimer = setInterval(() => {
    if (!document.hidden && (messagePending.value || session.value?.active && ['planning', 'cancel_pending'].includes(session.value.status))) void setup.pollStatus().catch(() => undefined);
}, 2000); });
onUnmounted(() => clearInterval(progressTimer));
const config = computed(() => manual.draft.value);
const pending = computed(() => config.value && manual.base.value ? setupChanges(manual.base.value.configuration, config.value) : []);
watch(() => route.query, query => { if (typeof query.zone !== 'string' && typeof query.device !== 'string') return; setup.context(typeof query.zone === 'string' ? query.zone : '', typeof query.device === 'string' ? query.device : ''); }, { immediate: true });
const missing = computed(() => missingFact(facts.value));
const proposalTargets = computed(() => {
    const p = proposal.value; if (!p) return [];
    if (p.lane === 'connectivity') return [{ kind: 'connection' as const, id: deviceContext.value, name: 'Подключение' }];
    const entities = ([['rooms', 'zone'], ['devices', 'device']] as const).flatMap(([key, kind]) => p.after[key].filter(e => JSON.stringify(e) !== JSON.stringify(p.before[key].find(b => b.id === e.id))).map(e => ({ kind, id: e.id, name: e.name })));
    const connections = (p.after.connections ?? []).filter(c => JSON.stringify(c) !== JSON.stringify(p.before.connections?.find(old => old.id === c.id))).map(c => ({ kind: 'connection' as const, id: '@' + c.id, name: c.name }));
    const targets = new Set([...p.after.bindings.filter(b => !p.before.bindings.some(old => JSON.stringify(old) === JSON.stringify(b))).map(b => b.target_id), ...(p.after.observations ?? []).filter(o => !p.before.observations?.some(old => JSON.stringify(old) === JSON.stringify(o))).map(o => o.target_id)]);
    const mappings = [...targets].map(id => ({ kind: 'connection' as const, id, name: 'Подключение: ' + (p.after.devices.find(d => d.id === id)?.name ?? id) }));
    return [...entities, ...connections, ...mappings];
});
</script>
<template><section class="panel setup-screen">
    <p>Опишите систему, проверьте предложения и примите их в план. Применение — отдельное подтверждение. AI и распознавание речи не управляют оборудованием.</p>
    <div v-if="!session?.active" class="inline-actions"><button class="primary" :disabled="setupBusy" @click="setup.startSetup()">Начать настройку</button><button v-if="session?.configuration && session.status !== 'applied'" :disabled="setupBusy" @click="setup.startSetup(true)">Восстановить серверный черновик</button><RouterLink to="/devices">Настроить вручную</RouterLink></div>
    <p v-if="session?.active && !owned" class="notice warning">Сессия принадлежит другому браузеру. Доступен только просмотр; захват не выполняется.</p>
    <p v-if="session?.status === 'entry_failed'" class="notice warning" role="alert">Не удалось подготовить локальный AI. Автоматического повтора нет; проверьте состояние ассистента.</p>
    <ForegroundStatus v-if="transitioning && !setupBusy" :label="entering ? 'Подготавливаем локальный AI… Это может занять некоторое время.' : 'Подготавливаем план или восстанавливаем ассистента…'" />
    <template v-if="owned"><div class="inline-actions"><button :disabled="!canCancel" @click="setup.cancelSetup()">Завершить настройку без Apply</button><button :disabled="!setup.ready.value || !!manual.task.value" @click="manual.prepare()">Сохранить и применить</button></div>
        <p v-if="messagePending || session?.status === 'planning'" role="status" data-testid="setup-planning-progress">{{ cancelRequested ? 'Остановка запрошена. Ждём завершения текущего шага…' : progressLabel }}</p>
        <fieldset :aria-busy="setupBusy || transitioning" :disabled="transitioning || setupBusy" class="setup-fields">
        <label>Явный контекст зоны<select v-model="zoneContext" :disabled="!!proposal"><option value="">Контекст не выбран</option><option v-for="z in config?.rooms" :key="z.id" :value="z.id">{{ z.name }}</option></select></label><button v-if="deviceContext && !proposal" :disabled="setupBusy" @click="manual.begin('device', deviceContext)">Изменить возможности вручную</button><div class="context-chips"><span v-if="zoneContext">Зона: {{ config?.rooms.find(z => z.id === zoneContext)?.name }} <button :disabled="!!proposal" @click="zoneContext = ''">×</button></span><span v-if="deviceContext">Устройство: {{ config?.devices.find(d => d.id === deviceContext)?.name }} <button :disabled="!!proposal" @click="deviceContext = ''">×</button></span></div>
        <ol class="conversation"><li v-for="(message, i) in conversation" :key="i"><strong>{{ message.role }}</strong><p>{{ message.text }}</p></li></ol>
        <div v-if="lane === 'connectivity'" class="form-section"><h2>Подключение устройства</h2><label>Устройство<select v-model="deviceContext" :disabled="!!proposal"><option value="">Выберите устройство</option><option v-for="d in config?.devices" :value="d.id" :key="d.id">{{ d.name }}</option></select></label><p>Известные факты пользователя:</p><dl class="facts"><dt>Endpoint</dt><dd>{{ facts.endpoint || 'Не указан' }}</dd><dt>Включение</dt><dd>{{ facts.on ? `${facts.on.method} ${facts.on.path} ${JSON.stringify(facts.on.body)}` : 'Не указано' }}</dd><dt>Выключение</dt><dd>{{ facts.off ? `${facts.off.method} ${facts.off.path} ${JSON.stringify(facts.off.body)}` : 'Не указано' }}</dd><dt>Чтение</dt><dd>{{ facts.noObserve ? 'Не предоставляется' : facts.observe ? `GET ${facts.observe}, поле ${facts.field || 'не указано'} → Питание` : 'Не указано' }}</dd></dl><p v-if="missing">{{ missing.question }}</p><label >Общее подключение: {{ selectedConsumers.join(', ') || 'ещё нет' }}<select v-model="sharedChoice" :disabled="!!proposal"><option value="">Выберите явно</option><option value="all">Изменить общее подключение для всех этих устройств</option><option value="separate">Создать отдельное подключение для выбранного устройства</option></select></label></div>
        <button v-if="deviceContext" :disabled="setupBusy || !!manual.task.value" @click="setup.manualConnectivity()">Настроить подключение вручную</button>
        <label>Способ настройки<select v-model="lane" :disabled="!!proposal || !!session?.message_incomplete"><option value="semantic">Описание системы и устройств с AI</option><option value="connectivity">Точные параметры HTTP-подключения</option></select></label>
        <form :aria-busy="setupBusy || messagePending || session?.status === 'planning'" @submit.prevent="setup.sendMessage()"><label>Ваша просьба<textarea v-model="composer" rows="8" :disabled="setupBusy" data-path="/text" aria-describedby="setup-prompt-size setup-prompt-help" placeholder="Опишите комнаты, устройства и нужные действия своими словами. Можно вставить несколько абзацев или список требований." /></label><p id="setup-prompt-help">Можно описать систему одним текстом. Неизвестные адреса и параметры подключения AI не должен придумывать. Пароли задаются отдельно в настройках доступа.</p><p id="setup-prompt-size" :class="{ 'field-error': promptSize.exceeds }" aria-live="polite">{{ promptSize.codepoints }} / {{ limits.message_codepoints }} символов · {{ promptSize.bytes }} / {{ limits.message_bytes }} байт<template v-if="zoneContext || deviceContext">, включая выбранный контекст</template>.<template v-if="promptSize.exceeds"> Текст превышает лимит. Сократите его или разделите на несколько просьб.</template></p><p v-if="zoneContext">Контекст, добавляемый к запросу: Зона: {{ config?.rooms.find(z => z.id === zoneContext)?.name }} .</p><p v-if="deviceContext && lane === 'semantic'">Контекст, добавляемый к запросу: Устройство: {{ config?.devices.find(d => d.id === deviceContext)?.name }} .</p><AdminVoice @transcript="composer = $event" @busy="manual.voiceBusy.value = $event" /><button type="submit" class="primary" :disabled="setupBusy || transitioning || messagePending || manual.voiceBusy.value || !!proposal || !!manual.task.value || !!session?.message_incomplete || promptSize.exceeds">{{ messagePending || session?.status === 'planning' ? 'ИИ обрабатывает…' : setupBusy ? 'Отправляем…' : 'Отправить' }}</button><p v-if="sendFeedback" :class="{ 'notice warning': sendFailed }" :role="sendFailed ? 'alert' : 'status'" data-testid="setup-send-feedback">{{ sendFeedback }}</p><button v-if="session?.message_incomplete" type="button" :disabled="setupBusy" @click="setup.sendMessage(true)">Повторить просьбу полностью</button><button v-if="session?.message_incomplete" type="button" :disabled="setupBusy || transitioning" @click="setup.discardMessage()">Исправить запрос</button></form>
        </fieldset>
    </template>
    <p v-if="session?.language_warning" class="notice warning" role="alert">{{ session.language_warning }} Проверьте речевые формы через «Изменить» перед принятием плана.</p>
    <button v-if="owned && session?.questions?.length && !session?.message_incomplete" :disabled="setupBusy" @click="setup.manualAfterQuestion()">Закрыть уточнение и продолжить вручную</button><p v-if="setupNotice" class="notice" role="status">{{ setupNotice }}</p><TaskErrors :issues="setupIssues" />
    <button v-if="setupIssues.length && owned" :disabled="setupBusy" @click="setup.restoreSession(true)">Перечитать серверный черновик для review</button><p v-if="setupIssues.length">План этого запроса не принят. Можно повторить запрос явно или <RouterLink to="/devices">заполнить вручную</RouterLink>.</p>
    <article v-if="proposal" class="proposal-card form-section"><h2>{{ !owned ? 'Серверный черновик · только просмотр' : proposal.lane === 'connectivity' ? 'Подключение из явных фактов · ещё не в плане' : 'AI-предложение · ещё не в плане' }}</h2><section v-for="(change, i) in proposalChanges" :key="i" class="review-change"><h3>{{ change.title }}</h3><p>{{ change.afterText }}</p><p v-if="change.consumers.length">Все затронутые устройства: {{ change.consumers.join(', ') }}</p></section><p>Оборудование командами ещё не проверялось.</p><details v-if="manual.advanced.value"><summary>Exact JSON</summary><pre>{{ JSON.stringify(proposal.after, null, 2) }}</pre></details><div v-if="owned" class="inline-actions"><button :disabled="setupBusy || transitioning" @click="setup.acceptProposal()">{{ proposal.lane === 'connectivity' ? 'Принять подключение в план' : 'Принять в план' }}</button><button v-for="target in proposalTargets" :key="target.kind + target.id" :disabled="setupBusy" @click="setup.editProposal(target.kind, target.id)">Изменить: {{ target.name }}</button><button :disabled="setupBusy" @click="setup.rejectProposal()">Отклонить</button><button v-if="proposal.lane === 'connectivity'" :disabled="setupBusy" @click="setup.probeProposal()">Проверить доступность</button></div><p v-if="probeResult" role="status">{{ probeResult }}</p></article>
    <section><h2>Текущий принятый план</h2><p v-if="!pending.length">Принятых изменений пока нет.</p><article v-for="(change, i) in pending" :key="i"><h3>{{ change.title }}</h3><p>{{ change.afterText }}</p></article><div v-if="owned && !proposal" class="inline-actions"><button v-for="device in config?.devices" :key="device.id" :disabled="setupBusy || transitioning" @click="setup.connectDevice(device.id)">Точные HTTP-параметры: {{ device.name }}</button></div></section>
</section></template>
